t.script:
(function() {
    function hideAgentMenu() {
        var links = document.querySelectorAll('a[href="/agent/shop"]');
        links.forEach(function(link) {
            var li = link.closest('li');
            if (li) {
                li.style.display = 'none';
            }
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', hideAgentMenu);
    } else {
        hideAgentMenu();
    }
})();
